/**
 * Typed wrappers around every backend endpoint used by the UI. Pages never build URLs themselves.
 * Mutations that move money take an idempotency key generated by the caller (see useIdempotencyKey).
 */
import { api, qs, request, requestWithMeta } from '@/lib/api';
import type {
  AdminOverview,
  AuditEntry,
  AuthResponse,
  DashboardSummary,
  DeliveryView,
  DirectoryEntry,
  LedgerView,
  MerchantBalance,
  MerchantDashboard,
  MerchantProfileView,
  MerchantReport,
  Meta,
  Notifications,
  Page,
  PaymentIntent,
  PayoutView,
  ReceiptView,
  RecipientView,
  ReconciliationReport,
  RefundView,
  SessionView,
  Statement,
  TopUpResponse,
  TransactionDetail,
  TransactionSummary,
  TransferView,
  UserProfile,
  WalletView,
  WebhookView,
  WebhookWithSecret,
} from '@/types/api';

export interface RegisterInput {
  fullName: string;
  email: string;
  password: string;
  accountType: 'CUSTOMER' | 'MERCHANT';
  currency: 'INR' | 'USD';
  businessName?: string;
  category?: string;
  acceptTerms: boolean;
}

export const authService = {
  login: (email: string, password: string) =>
    request<AuthResponse>('POST', '/api/v1/auth/login', { body: { email, password }, skipRefresh: true }),
  register: (input: RegisterInput) =>
    request<AuthResponse>('POST', '/api/v1/auth/register', { body: input, skipRefresh: true }),
  me: () => api.get<UserProfile>('/api/v1/auth/me'),
  updateProfile: (fullName: string) => api.patch<UserProfile>('/api/v1/auth/me', { fullName }),
  changePassword: (currentPassword: string, newPassword: string) =>
    api.post<void>('/api/v1/auth/password', { currentPassword, newPassword }),
  sessions: () => api.get<SessionView[]>('/api/v1/auth/sessions'),
  revokeSession: (id: string) => api.delete<void>(`/api/v1/auth/sessions/${id}`),
  logoutAll: () => api.post<void>('/api/v1/auth/logout-all'),
};

export const metaService = {
  get: () => api.get<Meta>('/api/v1/meta'),
};

export const dashboardService = {
  summary: () => api.get<DashboardSummary>('/api/v1/dashboard/summary'),
};

export const notificationService = {
  list: () => api.get<Notifications>('/api/v1/notifications'),
  markRead: () => api.post<void>('/api/v1/notifications/read'),
};

export const walletService = {
  get: () => api.get<WalletView>('/api/v1/wallet'),
  topUp: (amountMinor: number, currency: string, key: string) =>
    requestWithMeta<TopUpResponse>('POST', '/api/v1/wallet/sandbox/top-ups', {
      body: { amountMinor, currency },
      idempotencyKey: key,
    }),
  statement: (p: { from?: string; to?: string; page?: number; size?: number }) =>
    api.get<Statement>(`/api/v1/wallet/statement${qs(p)}`),
};

export interface TransactionFilter {
  type?: string;
  currency?: string;
  direction?: string;
  q?: string;
  from?: string;
  to?: string;
  sort?: string;
  page?: number;
  size?: number;
}

export const transactionService = {
  list: (f: TransactionFilter) => api.get<Page<TransactionSummary>>(`/api/v1/transactions${qs({ ...f })}`),
  get: (id: string) => api.get<TransactionDetail>(`/api/v1/transactions/${id}`),
  ledger: (id: string) => api.get<LedgerView>(`/api/v1/transactions/${id}/ledger`),
};

export const transferService = {
  lookup: (recipient: string) => api.post<RecipientView>('/api/v1/transfers/recipient-lookup', { recipient }),
  create: (
    body: { recipient: string; amountMinor: number; currency: string; description?: string },
    key: string,
  ) => requestWithMeta<TransferView>('POST', '/api/v1/transfers', { body, idempotencyKey: key }),
  list: (p: { direction?: string; q?: string; page?: number; size?: number }) =>
    api.get<Page<TransferView>>(`/api/v1/transfers${qs(p)}`),
  get: (id: string) => api.get<TransferView>(`/api/v1/transfers/${id}`),
};

export interface PaymentFilter {
  status?: string;
  currency?: string;
  q?: string;
  from?: string;
  to?: string;
  sort?: string;
  page?: number;
  size?: number;
}

export const paymentService = {
  merchants: (q?: string) => api.get<DirectoryEntry[]>(`/api/v1/merchants${qs({ q })}`),
  create: (
    body: {
      merchantId: string;
      amountMinor: number;
      currency: string;
      description?: string;
      metadata?: Record<string, string>;
    },
    key: string,
  ) => request<PaymentIntent>('POST', '/api/v1/payment-intents', { body, idempotencyKey: key }),
  confirm: (id: string, key: string) =>
    requestWithMeta<PaymentIntent>('POST', `/api/v1/payment-intents/${id}/confirm`, { idempotencyKey: key }),
  cancel: (id: string) => api.post<PaymentIntent>(`/api/v1/payment-intents/${id}/cancel`),
  list: (f: PaymentFilter) => api.get<Page<PaymentIntent>>(`/api/v1/payment-intents${qs({ ...f })}`),
  get: (id: string) => api.get<PaymentIntent>(`/api/v1/payment-intents/${id}`),
  refunds: (id: string) => api.get<RefundView[]>(`/api/v1/payments/${id}/refunds`),
  refund: (id: string, body: { amountMinor?: number; reason?: string }, key: string) =>
    request<RefundView>('POST', `/api/v1/payments/${id}/refunds`, { body, idempotencyKey: key }),
};

export const merchantService = {
  dashboard: () => api.get<MerchantDashboard>('/api/v1/merchant/dashboard'),
  balance: () => api.get<MerchantBalance>('/api/v1/merchant/balance'),
  payments: (f: PaymentFilter) => api.get<Page<PaymentIntent>>(`/api/v1/merchant/payments${qs({ ...f })}`),
  report: (from?: string, to?: string) => api.get<MerchantReport>(`/api/v1/merchant/reports${qs({ from, to })}`),
  payout: (amountMinor: number, key: string) =>
    request<PayoutView>('POST', '/api/v1/merchant/payouts', { body: { amountMinor }, idempotencyKey: key }),
  payouts: (page = 0) => api.get<Page<PayoutView>>(`/api/v1/merchant/payouts${qs({ page, size: 10 })}`),
  profile: () => api.get<MerchantProfileView>('/api/v1/merchant/profile'),
  updateProfile: (body: { businessName: string; category: string; supportEmail?: string; website?: string }) =>
    api.patch<MerchantProfileView>('/api/v1/merchant/profile', body),
};

export const webhookService = {
  list: () => api.get<WebhookView[]>('/api/v1/merchant/webhooks'),
  eventTypes: () => api.get<string[]>('/api/v1/merchant/webhooks/event-types'),
  create: (body: { url: string; description?: string; events: string[] }) =>
    api.post<WebhookWithSecret>('/api/v1/merchant/webhooks', body),
  update: (id: string, body: { url?: string; description?: string; events?: string[]; enabled?: boolean }) =>
    api.patch<WebhookView>(`/api/v1/merchant/webhooks/${id}`, body),
  remove: (id: string) => api.delete<void>(`/api/v1/merchant/webhooks/${id}`),
  rotate: (id: string) => api.post<WebhookWithSecret>(`/api/v1/merchant/webhooks/${id}/rotate-secret`),
  test: (id: string) => api.post<DeliveryView>(`/api/v1/merchant/webhooks/${id}/test`),
  deliveries: (id: string, p: { status?: string; page?: number; size?: number }) =>
    api.get<Page<DeliveryView>>(`/api/v1/merchant/webhooks/${id}/deliveries${qs(p)}`),
  delivery: (id: string, deliveryId: string) =>
    api.get<DeliveryView>(`/api/v1/merchant/webhooks/${id}/deliveries/${deliveryId}`),
  replay: (id: string, deliveryId: string) =>
    api.post<DeliveryView>(`/api/v1/merchant/webhooks/${id}/replay`, { deliveryId }),
  receipts: () => api.get<ReceiptView[]>('/api/v1/merchant/webhooks/sandbox-receipts'),
};

export const adminService = {
  reconciliation: () => api.get<ReconciliationReport>('/api/v1/admin/reconciliation'),
  overview: () => api.get<AdminOverview>('/api/v1/admin/overview'),
  audit: (p: { action?: string; page?: number; size?: number }) =>
    api.get<Page<AuditEntry>>(`/api/v1/admin/audit-logs${qs(p)}`),
  reverse: (transactionId: string, reason: string, key: string) =>
    request<{ transactionId: string; reference: string }>(
      'POST',
      `/api/v1/admin/ledger/transactions/${transactionId}/reversal`,
      { body: { reason }, idempotencyKey: key },
    ),
};
